// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address claimer, uint256 amount) public {
        vm.assume(claimer != address(0));
        vm.assume(amount > 0);

        // Ensure we can call claim without revert for valid inputs
        // The property: owner() never returns address(0) before or after any operation
        vm.prank(claimer);
        address ownerBefore = c.owner();

        // Try to claim - may revert due to various conditions, but that's fine
        (bool success, ) = address(c).call(abi.encodeWithSignature("claim(address,uint256)", claimer, amount));

        // After the call, check owner() again
        address ownerAfter = c.owner();

        // General rule: owner() must never return address(0)
        assertTrue(ownerBefore != address(0) && ownerAfter != address(0));
    }
}

