pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address anyCaller) public {
        vm.assume(anyCaller != address(0));

        // Get the expected owner (deployer in setUp, but we just check it's non-zero and matches code logic)
        // Since C uses OwnableUpgradeable, owner() should return the deployer address initially.
        // The bug replaces owner() with a constant zero address 0x01, so we check owner() != address(0x01).
        // But more generally, the property is: owner() should return the address that deployed the contract.
        // The reference: owner() == address(this) (since Test contract deploys it).
        // The mutant: owner() == 0x0000000000000000000000000000000000000001.
        // So we assert: owner() == address(this).

        address owner = c.owner();
        assertTrue(owner == address(this), "Owner should be the deployer");
    }
}

