import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount) public {
        // Bound amount to avoid overflow issues
        vm.assume(amount > 0 && amount <= 1e30);
        // Ensure caller is not zero address (claim will revert otherwise)
        vm.assume(caller != address(0));

        // First, set up a valid keeper via setKeeper (owner is c.deployer, which is this test contract)
        address keeper = address(0x1234);
        c.setKeeper(keeper);

        // Then call claim via caller with the given amount
        // The claim may revert due to insufficient shares or other reasons; we only assert on non-reverting paths
        uint256 snapshot = vm.snapshot();
        (bool success, ) = address(c).call(abi.encodeWithSignature("claim(address,uint256)", caller, amount));
        if (!success) {
            // Reverting call: skip the assertion (no state change expected)
            vm.revertTo(snapshot);
            return;
        }

        // The general rule: after a successful claim, the keeper should still be the one we set
        // In the reference, keeper unchanged; in buggy version, keeper becomes address(0)
        assertTrue(c.keeper() == keeper, "keeper changed unexpectedly after claim");
    }
}

