pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant INITIAL_KEEPER = address(0x1234);

    function setUp() public {
        c = new C();
        // Initialize with a specific keeper address
        // The initialize function expects: _sGlp, _usdc, _rewardRouter, _glpManager, _dnGmxJuniorVault, _keeper
        // We can pass zero addresses for the first 5, but keeper must be set.
        // However, C's initialize calls __GMXBatchingManager_init which sets keeper = _keeper.
        // We need to call initialize to set the keeper. Use dummy addresses for the rest.
        vm.assume(INITIAL_KEEPER != address(0)); // keeper must be non-zero for the test to be meaningful? Not strictly necessary, but okay.
        c.initialize(
            IERC20(address(0)),
            IERC20(address(0)),
            IRewardRouterV2(address(0)),
            IGlpManager(address(0)),
            address(0),
            INITIAL_KEEPER
        );
    }

    function testFuzz_property(address claimer, address receiver, uint256 amount) public {
        // Bound amount to avoid overflow issues
        amount = bound(amount, 0, 1e30);

        // Drive c through its public surface, ending in a call to claim
        // If the claim is expected to revert (e.g., receiver == 0 or amount == 0), the test should still work
        // because we only check the keeper value after the call.
        // To handle reverts, we try/catch.
        address keeperBefore = c.keeper();

        (bool success, bytes memory) = address(c).call(
            abi.encodeWithSignature("claim(address,uint256)", receiver, amount)
        );
        // We don't care about success; we just check keeper after the call
        address keeperAfter = c.keeper();

        assertTrue(keeperAfter == keeperBefore, "Keeper should remain unchanged");
    }
}

