import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address newKeeper, address receiver, uint256 amount) public {
        // Assume valid inputs
        vm.assume(caller != address(0));
        vm.assume(receiver != address(0));
        vm.assume(amount > 0 && amount <= type(uint128).max);

        // Record initial keeper
        address initialKeeper = c.keeper();

        // Optionally call setKeeper with a random address
        if (newKeeper != address(0) && caller != address(0)) {
            vm.prank(caller);
            // Only owner can call setKeeper; if caller is not owner, it reverts, that's fine
            // We'll handle both cases
            (bool successSetKeeper, ) = address(c).call(abi.encodeWithSignature("setKeeper(address)", newKeeper));
            if (successSetKeeper) {
                // If setKeeper succeeded, newKeeper should be the keeper after the call
                // We'll verify that claim doesn't change it
            }
        }

        // Take snapshot before claim
        address keeperBeforeClaim = c.keeper();

        // Call claim
        vm.prank(caller);
        (bool successClaim, ) = address(c).call(abi.encodeWithSignature("claim(address,uint256)", receiver, amount));

        // If claim succeeded, check keeper didn't change
        if (successClaim) {
            assertTrue(c.keeper() == keeperBeforeClaim, "keeper changed after claim");
        }
        // If claim reverted, still check keeper didn't change
        else {
            assertTrue(c.keeper() == keeperBeforeClaim, "keeper changed after revert");
        }
    }
